/** Number formatting shared by every chart, tooltip and table of the analytics view. */

const integer = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const oneDecimal = new Intl.NumberFormat("en-US", { maximumFractionDigits: 1 });

/** 1234 → "1,234"; 0.5 → "0.5"; 12.345 → "12.3". */
export function formatNumber(n: number): string {
  if (!Number.isFinite(n)) return "–";
  return Math.abs(n) >= 100 || Number.isInteger(n) ? integer.format(n) : oneDecimal.format(n);
}

/** 12345 → "12.3k", 1_250_000 → "1.3M": for axis ticks, where space is short. */
export function formatCompact(n: number): string {
  if (!Number.isFinite(n)) return "–";
  const abs = Math.abs(n);
  if (abs >= 1e6) return `${oneDecimal.format(n / 1e6)}M`;
  if (abs >= 1e4) return `${oneDecimal.format(n / 1e3)}k`;
  return formatNumber(n);
}

/** Share 0–1 → "42%"; below 10 % one decimal ("4.2%"); exact zero "0%". */
export function formatPercent(share: number): string {
  if (!Number.isFinite(share)) return "–";
  const pct = share * 100;
  if (pct === 0) return "0%";
  if (Math.abs(pct) < 10) return `${oneDecimal.format(pct)}%`;
  return `${integer.format(pct)}%`;
}

/** Difference of two shares in percentage points: +3.4 pp, −12 pp. */
export function formatPoints(delta: number): string {
  if (!Number.isFinite(delta)) return "–";
  const pp = delta * 100;
  const sign = pp > 0 ? "+" : pp < 0 ? "−" : "±";
  const abs = Math.abs(pp);
  return `${sign}${abs < 10 ? oneDecimal.format(abs) : integer.format(abs)} pp`;
}

/**
 * Round axis ticks from 0 (or min) to at least max: steps of 1, 2 or 5 × 10^n.
 * niceTicks(0, 87) → [0, 20, 40, 60, 80, 100].
 */
export function niceTicks(min: number, max: number, count = 5): number[] {
  if (!Number.isFinite(min) || !Number.isFinite(max)) return [0, 1];
  if (max <= min) max = min + 1;
  const raw = (max - min) / Math.max(1, count);
  const magnitude = 10 ** Math.floor(Math.log10(raw));
  const step = [1, 2, 5, 10].map((m) => m * magnitude).find((s) => s >= raw) ?? 10 * magnitude;
  const start = Math.floor(min / step) * step;
  const ticks: number[] = [];
  for (let v = start; v < max + step * 0.5 && ticks.length < 50; v += step) {
    ticks.push(Number(v.toFixed(10)));
  }
  if (ticks[ticks.length - 1]! < max) ticks.push(Number((start + ticks.length * step).toFixed(10)));
  return ticks;
}

/** Shortens a label to `max` characters with an ellipsis; the full text goes in a tooltip. */
export function truncate(label: string, max: number): string {
  return label.length <= max ? label : `${label.slice(0, Math.max(1, max - 1))}…`;
}

import { describe, expect, it } from "vitest";
import {
  formatCompact,
  formatNumber,
  formatPercent,
  formatPoints,
  niceTicks,
  truncate,
} from "./format";

describe("chart formatting", () => {
  it("formats counts, shares and differences", () => {
    expect(formatNumber(1234)).toBe("1,234");
    expect(formatNumber(12.345)).toBe("12.3");
    expect(formatCompact(12_345)).toBe("12.3k");
    expect(formatCompact(1_250_000)).toBe("1.3M");
    expect(formatPercent(0.4249)).toBe("42%");
    expect(formatPercent(0.042)).toBe("4.2%");
    expect(formatPercent(0)).toBe("0%");
    expect(formatPoints(0.034)).toBe("+3.4 pp");
    expect(formatPoints(-0.12)).toBe("−12 pp");
    expect(formatNumber(Number.NaN)).toBe("–");
  });

  it("makes round ticks that cover the maximum", () => {
    expect(niceTicks(0, 87)).toEqual([0, 20, 40, 60, 80, 100]);
    expect(niceTicks(0, 1)).toEqual([0, 0.2, 0.4, 0.6, 0.8, 1]);
    expect(niceTicks(0, 0)).toEqual([0, 0.2, 0.4, 0.6, 0.8, 1]);
    const ticks = niceTicks(0, 4321);
    expect(ticks[0]).toBe(0);
    expect(ticks.at(-1)!).toBeGreaterThanOrEqual(4321);
  });

  it("truncates long labels", () => {
    expect(truncate("Infotainment & display", 12)).toBe("Infotainmen…");
    expect(truncate("Seats", 12)).toBe("Seats");
  });
});

import { useState, type ReactNode } from "react";
import { cx } from "@/lib/cx";
import { ChartIcon, TableIcon } from "@/components/ui/icons";

/** The same numbers as a chart, for reading exact values and for screen readers. */
export interface ChartTable {
  columns: string[];
  rows: (string | number)[][];
}

/**
 * Frame of every chart: title, one-line subtitle (what is counted), optional controls, and a
 * chart ⇄ table switch. The table is always available, so no value depends on colour alone.
 */
export function ChartCard({
  title,
  subtitle,
  actions,
  legend,
  footnote,
  table,
  className,
  testId,
  children,
}: {
  title: string;
  subtitle?: ReactNode;
  actions?: ReactNode;
  legend?: ReactNode;
  footnote?: ReactNode;
  table?: ChartTable;
  className?: string;
  testId?: string;
  children: ReactNode;
}) {
  const [showTable, setShowTable] = useState(false);
  return (
    <section
      data-testid={testId}
      className={cx("flex min-w-0 flex-col rounded-xl border border-line bg-panel", className)}
    >
      <header className="flex flex-wrap items-start justify-between gap-3 px-4 pt-3">
        <div className="min-w-0">
          <h3 className="text-sm font-semibold text-ink">{title}</h3>
          {subtitle && <p className="mt-0.5 text-xs text-muted">{subtitle}</p>}
        </div>
        <div className="flex shrink-0 items-center gap-2">
          {actions}
          {table && (
            <button
              type="button"
              className="rounded-md p-1 text-muted hover:bg-panel-2 hover:text-ink focus-visible:outline-2 focus-visible:outline-brand"
              aria-label={showTable ? `Show ${title} as a chart` : `Show ${title} as a table`}
              title={showTable ? "Show chart" : "Show table"}
              onClick={() => setShowTable((v) => !v)}
            >
              {showTable ? <ChartIcon className="size-4" /> : <TableIcon className="size-4" />}
            </button>
          )}
        </div>
      </header>
      {legend && !showTable && <div className="px-4 pt-2">{legend}</div>}
      <div className="min-h-0 flex-1 px-4 pt-2 pb-3">
        {showTable && table ? <DataTable table={table} /> : children}
      </div>
      {footnote && <div className="border-t border-line px-4 py-2 text-xs text-muted">{footnote}</div>}
    </section>
  );
}

export function DataTable({ table }: { table: ChartTable }) {
  return (
    <div className="max-h-80 overflow-auto rounded-lg border border-line">
      <table className="w-full text-left text-xs">
        <thead className="sticky top-0 bg-panel-2 text-muted">
          <tr>
            {table.columns.map((c, i) => (
              <th key={i} className={cx("px-3 py-2 font-medium", i > 0 && "text-right")}>
                {c}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {table.rows.map((row, r) => (
            <tr key={r} className="border-t border-line">
              {row.map((cell, i) => (
                <td
                  key={i}
                  className={cx("px-3 py-1.5 text-ink", i > 0 && "text-right tabular-nums")}
                >
                  {cell}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/** Shown in place of a chart when the data has nothing to plot. Says why, never a blank box. */
export function EmptyChart({ children }: { children: ReactNode }) {
  return (
    <div className="flex min-h-32 items-center justify-center rounded-lg border border-dashed border-line px-6 py-8 text-center text-sm text-muted">
      {children}
    </div>
  );
}

import type { ReactNode } from "react";

/** What a chart shows on hover: an anchor point in the chart's own pixels and the content. */
export interface HoverState {
  x: number;
  y: number;
  content: ReactNode;
}

/**
 * A tooltip positioned inside a `relative` chart container. It flips to the left of the pointer
 * in the right half of the chart so it never runs off the edge. Text uses ink tokens; a colour
 * swatch next to a value carries the series identity.
 */
export function ChartTooltip({ hover, width }: { hover: HoverState | null; width: number }) {
  if (!hover) return null;
  const flip = hover.x > width / 2;
  return (
    <div
      role="tooltip"
      className="pointer-events-none absolute z-10 max-w-72 rounded-lg border border-line bg-panel px-3 py-2 text-xs text-ink shadow-lg"
      style={{
        left: flip ? undefined : hover.x + 12,
        right: flip ? Math.max(0, width - hover.x + 12) : undefined,
        top: Math.max(0, hover.y - 12),
      }}
    >
      {hover.content}
    </div>
  );
}

/** One "■ label  value" line inside a tooltip. */
export function TooltipRow({
  color,
  label,
  value,
}: {
  color?: string;
  label: ReactNode;
  value: ReactNode;
}) {
  return (
    <div className="flex items-center justify-between gap-4 py-0.5">
      <span className="flex min-w-0 items-center gap-2">
        {color && (
          <span
            aria-hidden="true"
            className="inline-block size-2.5 shrink-0 rounded-sm"
            style={{ background: color }}
          />
        )}
        <span className="truncate text-muted">{label}</span>
      </span>
      <span className="font-medium tabular-nums">{value}</span>
    </div>
  );
}

/** Legend for two or more series: swatch + label, in series order. */
export function Legend({
  items,
}: {
  items: { key: string; label: string; color: string; dashed?: boolean }[];
}) {
  if (items.length < 2) return null;
  return (
    <ul className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted" aria-label="Legend">
      {items.map((item) => (
        <li key={item.key} className="flex items-center gap-1.5">
          <span
            aria-hidden="true"
            className="inline-block h-2.5 w-3 rounded-sm"
            style={
              item.dashed
                ? { border: `2px dashed ${item.color}`, background: "transparent" }
                : { background: item.color }
            }
          />
          {item.label}
        </li>
      ))}
    </ul>
  );
}

import { useLayoutEffect, useRef, useState } from "react";

/**
 * Width of a chart container in CSS pixels, kept current with a ResizeObserver, so SVG charts
 * draw at their real size (crisp 2px lines, readable labels) instead of being scaled.
 */
export function useWidth<T extends HTMLElement = HTMLDivElement>(fallback = 600) {
  const ref = useRef<T>(null);
  const [width, setWidth] = useState(fallback);
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    setWidth(el.clientWidth || fallback);
    const observer = new ResizeObserver((entries) => {
      const w = entries[0]?.contentRect.width;
      if (w && Math.abs(w - width) >= 1) setWidth(Math.floor(w));
    });
    observer.observe(el);
    return () => observer.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return [ref, width] as const;
}

