/** Lowercase, Unicode NFKD with combining marks removed (ä→a, é→e), ß→ss, curly quotes → straight, whitespace collapsed, trimmed. */
export function foldText(s: string): string;
/** A word of the original text with its character range [start, end) in the ORIGINAL string and its folded form. Words are runs of letters/digits (Unicode \p{L}\p{N}), may contain inner apostrophes or hyphens ("don't", "e-mail", "head-up"). */
export interface Word { text: string; folded: string; start: number; end: number }
export function words(s: string): Word[];
/** Folded words of length ≥ 2 (pure numbers kept only if ≥ 2 chars). */
export function tokenize(s: string): string[];
/** English + German stopwords (folded), ~250 each: articles, pronouns, auxiliaries, prepositions, conjunctions, very common verbs/adverbs ("is","was","have","very","also","just","really","car"? — NO: keep domain words like "car", "seat", "auto" OUT of the stopword list; only function words), plus filler like "etc", "e.g", "eg". */
export const STOPWORDS: ReadonlySet<string>;
/** tokenize() minus stopwords and minus tokens that are only digits. */
export function contentTokens(s: string): string[];
/**
 * A phrase query the user types to count how many records say something.
 * Syntax: alternatives separated by "|" or by " OR " (case-insensitive) or by "," ; each alternative is a sequence of words that must appear consecutively (word boundaries, folded, so "Sitz" matches "sitz", "Muller" matches "Müller"); a word ending in "*" matches any word with that prefix ("charg*" matches "charging", "charger"); double quotes are allowed and ignored ("\"seat heating\"" = seat heating). Empty alternatives are dropped. Returns null when nothing is left.
 */
export interface PhraseQuery { raw: string; alternatives: { word: string; prefix: boolean }[][] }
export function parsePhrase(raw: string): PhraseQuery | null;
/** True when any alternative occurs in the text. */
export function matchesPhrase(text: string, query: PhraseQuery): boolean;
/** Character ranges [start, end) in the ORIGINAL text of every match (for highlighting), sorted, non-overlapping (merge overlaps). */
export function phraseRanges(text: string, query: PhraseQuery): [number, number][];
/** Document frequency: in how many texts a term occurs at least once. */
export interface TermCount { term: string; docs: number; share: number }
/**
 * The most frequent content terms by document frequency (a text counts once per term). ngram 1 = single content tokens; ngram 2 = pairs of consecutive content tokens within one text, joined by a space, where neither is a stopword (computed on the sequence of tokenize() output, skipping pairs that contain a stopword). Excludes terms with fewer than minDocs (default 2) documents. Sorted by docs desc, then term asc (deterministic). share = docs / texts.length. limit default 30.
 */
export function topTerms(texts: readonly string[], opts?: { limit?: number; minDocs?: number; ngram?: 1 | 2 }): TermCount[];
/**
 * Terms that set group A apart from group B (unigrams and bigrams together): weighted log-odds ratio with an informative Dirichlet prior (Monroe, Colaresi & Quinn 2008), using document frequencies; the prior is the combined A+B counts scaled to a total of 0.01 × number of distinct terms... (choose a standard, documented alpha: alpha_w = 0.01 * combined count of w is fine; document it in the doc comment). Returns the terms with the highest z-scores (over-represented in A), only those with docsA ≥ minDocs (default 3) and z > 1.96. shareA = docsA / a.length, shareB = docsB / b.length. Sorted by z desc, then term asc. limit default 15.
 */
export interface DistinctiveTerm { term: string; docsA: number; docsB: number; shareA: number; shareB: number; z: number }
export function distinctiveTerms(a: readonly string[], b: readonly string[], opts?: { limit?: number; minDocs?: number }): DistinctiveTerm[];
/** A short excerpt around the first match: up to `radius` characters on each side, cut at word boundaries, with "…" where text was cut. Returns { text, ranges } where ranges are the match ranges relative to the excerpt. When there is no match, the first 2*radius characters. radius default 90. */
export function excerpt(text: string, query: PhraseQuery | null, radius?: number): { text: string; ranges: [number, number][] };
```

