import { useEffect, useMemo, useState } from "react";
import type { WorkflowBlock, WorkflowGraph, WorkflowRun } from "@reqflow/core";
import { api } from "@/lib/api";
import { useSettings } from "@/lib/settings";
import { buildDataset } from "./engine/dataset";
import type { AnalyticsDataset, AnalyticsInput } from "./engine/types";
import { loadInputs, planInputs } from "./load";

export type LoadState =
  | { status: "loading" }
  | { status: "ready"; inputs: AnalyticsInput[]; dataset: AnalyticsDataset }
  | { status: "error"; message: string };

/**
 * Reads every input of the Analytics block (saved run outputs, or a live read of connected
 * sources) and builds the dataset the charts count. Reloads when the wiring, the run, the
 * column choices or `reload` change; late answers of older reads are dropped.
 */
export function useAnalyticsData({
  root,
  path,
  block,
  run,
  reload,
}: {
  root: WorkflowGraph;
  path: string[];
  block: WorkflowBlock;
  run: WorkflowRun | null;
  reload: number;
}): LoadState {
  const scope = useSettings((s) => s.settings.defaultScope);
  const plans = useMemo(() => {
    try {
      return { ok: true as const, plans: planInputs(root, path, block.id) };
    } catch (err) {
      return { ok: false as const, message: err instanceof Error ? err.message : String(err) };
    }
  }, [root, path, block.id]);
  const wiring = plans.ok
    ? JSON.stringify(
        plans.plans.map((p) => [p.label, p.edges.map(({ edge, source }) => [edge, source?.params])]),
      )
    : "";
  const countryColumn = String(block.params.countryColumn ?? "");
  const timeColumn = String(block.params.timeColumn ?? "");

  const [state, setState] = useState<LoadState>({ status: "loading" });

  useEffect(() => {
    if (!plans.ok) {
      setState({ status: "error", message: plans.message });
      return;
    }
    let cancelled = false;
    setState({ status: "loading" });
    void loadInputs(plans.plans, {
      run,
      scope,
      blockOutput: api.runs.blockOutput,
      preview: api.blocks.preview,
    }).then(
      (inputs) => {
        if (cancelled) return;
        // Let the "Analysing…" state paint before the (synchronous) counting starts.
        setTimeout(() => {
          if (cancelled) return;
          try {
            const dataset = buildDataset(inputs, { countryColumn, timeColumn });
            setState({ status: "ready", inputs, dataset });
          } catch (err) {
            setState({ status: "error", message: err instanceof Error ? err.message : String(err) });
          }
        }, 0);
      },
      (err: unknown) => {
        if (!cancelled) {
          setState({ status: "error", message: err instanceof Error ? err.message : String(err) });
        }
      },
    );
    return () => {
      cancelled = true;
    };
    // `wiring` stands for the plans' content; `plans` itself changes identity on every edit.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [wiring, run?.id, run?.status, scope, countryColumn, timeColumn, reload]);

  return state;
}

import { createContext, useContext } from "react";
import type { TimeGranularity } from "@reqflow/core";
import type {
  AnalyticsDataset,
  AnalyticsFilters,
  AnalyticsInput,
  AnalyticsRow,
  Granularity,
} from "./engine/types";

/** What every analytics tab reads: the dataset, the filtered rows and the shared controls. */
export interface AnalyticsContextValue {
  dataset: AnalyticsDataset;
  inputs: AnalyticsInput[];
  /** Rows after the filter bar. Every chart counts these. */
  rows: AnalyticsRow[];
  /** Rows of the whole dataset (for stable colours and "of all" comparisons). */
  allRows: AnalyticsRow[];
  filters: AnalyticsFilters;
  setFilters(patch: Partial<AnalyticsFilters>): void;
  /** Fixed colour of an input (its port position). */
  inputColor(index: number): string;
  /** Fixed colour of a country (by its rank in the whole dataset; later ones are "Other"). */
  countryColor(code: string): string;
  /** The timeline buckets: the block's setting, resolved from the data when "auto". */
  granularity: Granularity;
  granularitySetting: TimeGranularity;
  setGranularity(value: TimeGranularity): void;
  /** Tracked phrases, saved in the block's params so they stay with the workflow. */
  phrases: string[];
  setPhrases(phrases: string[]): void;
  blockLabel: string;
}

export const AnalyticsContext = createContext<AnalyticsContextValue | null>(null);

export function useAnalytics(): AnalyticsContextValue {
  const value = useContext(AnalyticsContext);
  if (!value) throw new Error("useAnalytics() must be used inside the analytics view.");
  return value;
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useStore } from "zustand";
import {
  graphAt,
  TimeGranularity,
  walkBlocks,
  type WorkflowBlock,
  type WorkflowGraph,
  type WorkflowRun,
} from "@reqflow/core";
import { dataflowStore, useDataflow } from "@/components/dataflow/store";
import { runStore } from "@/components/dataflow/run-session";
import { BlockIcon } from "@/components/dataflow/BlockIcon";
import { GROUP_STYLE } from "@/components/dataflow/groups";
import { MStripe } from "@/components/ui/MStripe";
import { Button } from "@/components/ui/Button";
import { MaximizeIcon, MinimizeIcon, XIcon } from "@/components/ui/icons";
import { cx } from "@/lib/cx";
import { AnalyticsContext, type AnalyticsContextValue } from "./context";
import { applyFilters, colorSlots, countByCountry, peopleCount, timeExtent } from "./engine/aggregate";
import { autoGranularity } from "./engine/time";
import type { AnalyticsFilters, AnalyticsInput } from "./engine/types";
import { formatNumber } from "./charts/format";
import { OTHER_COLOR, seriesColor } from "./charts/palette";
import { FilterBar } from "./FilterBar";
import { useAnalyticsData, type LoadState } from "./useAnalyticsData";
import { OverviewTab } from "./tabs/OverviewTab";
import { CountriesTab } from "./tabs/CountriesTab";
import { TimelineTab } from "./tabs/TimelineTab";
import { VoiceTab } from "./tabs/VoiceTab";
import { TopicsTab } from "./tabs/TopicsTab";
import { CompareTab } from "./tabs/CompareTab";
import { FlowTab } from "./tabs/FlowTab";
import { QualityTab } from "./tabs/QualityTab";

const TABS = [
  { id: "overview", label: "Overview", Component: OverviewTab },
  { id: "countries", label: "Countries", Component: CountriesTab },
  { id: "timeline", label: "Timeline", Component: TimelineTab },
  { id: "voice", label: "What people say", Component: VoiceTab },
  { id: "topics", label: "Topics & sentiment", Component: TopicsTab },
  { id: "compare", label: "Compare sources", Component: CompareTab },
  { id: "flow", label: "Flow", Component: FlowTab },
  { id: "quality", label: "Data quality", Component: QualityTab },
] as const;
type TabId = (typeof TABS)[number]["id"];

/** Mounted once on the Data Flow page; shows the analytics of the block opened in the store. */
export function AnalyticsHost() {
  const open = useDataflow((s) => s.analytics);
  const editorRoot = useDataflow((s) => s.root);
  const currentRun = useStore(runStore, (s) => s.run);
  // The saved run, when it contains this block: show exactly what arrived in it.
  const inRun = useMemo(
    () =>
      currentRun && open
        ? [...walkBlocks(currentRun.graph)].some(({ block }) => block.id === open.blockId)
        : false,
    [currentRun, open],
  );
  const run = inRun ? currentRun : null;
  const root = run?.graph ?? editorRoot;
  const path = useMemo(() => {
    if (!open) return [];
    if (!run) return open.path;
    return [...walkBlocks(run.graph)].find(({ block }) => block.id === open.blockId)?.path ?? open.path;
  }, [open, run]);
  const block = useMemo(() => {
    if (!open) return null;
    try {
      return graphAt(root, path).blocks.find((b) => b.id === open.blockId) ?? null;
    } catch {
      return null; // its workplace was deleted
    }
  }, [root, path, open]);
  // Params (inputs' names, phrases, columns) always come from the editor, so edits show at once.
  const editorBlock = useMemo(() => {
    if (!open) return null;
    try {
      return graphAt(editorRoot, open.path).blocks.find((b) => b.id === open.blockId) ?? null;
    } catch {
      return null;
    }
  }, [editorRoot, open]);

  useEffect(() => {
    if (open && !block) dataflowStore.getState().closeAnalytics();
  }, [open, block]);

  if (!open || !block) return null;
  return (
    <AnalyticsScreen
      key={`${run?.id ?? "preview"}:${block.id}`}
      root={root}
      path={path}
      block={editorBlock ?? block}
      runBlock={block}
      run={run}
    />
  );
}

function AnalyticsScreen({
  root,
  path,
  block,
  runBlock,
  run,
}: {
  root: WorkflowGraph;
  path: string[];
  block: WorkflowBlock;
  runBlock: WorkflowBlock;
  run: WorkflowRun | null;
}) {
  const screenRef = useRef<HTMLDivElement>(null);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [reload, setReload] = useState(0);
  const [tab, setTab] = useState<TabId>("overview");
  const state = useAnalyticsData({ root, path, block: runBlock, run, reload });

  // Opening the analytics takes the whole screen; Esc leaves full screen first, then closes.
  useEffect(() => {
    const el = screenRef.current;
    el?.focus();
    const onChange = () => setIsFullscreen(document.fullscreenElement === el);
    document.addEventListener("fullscreenchange", onChange);
    el?.requestFullscreen?.().catch(() => {
      /* not allowed here (no user gesture, or a test window): the overlay still fills the app */
    });
    return () => {
      document.removeEventListener("fullscreenchange", onChange);
      if (document.fullscreenElement === el) void document.exitFullscreen().catch(() => {});
    };
  }, []);
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && !document.fullscreenElement) {
        dataflowStore.getState().closeAnalytics();
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);

  const toggleFullscreen = () => {
    const el = screenRef.current;
    if (!el) return;
    if (document.fullscreenElement) void document.exitFullscreen().catch(() => {});
    else void el.requestFullscreen?.().catch(() => {});
  };

  return (
    <div
      ref={screenRef}
      role="dialog"
      aria-modal="true"
      aria-labelledby="analytics-title"
      data-testid="analytics-view"
      tabIndex={-1}
      className="fixed inset-0 z-50 flex flex-col bg-canvas text-ink outline-none"
    >
      <MStripe className="rounded-none" />
      <header className="flex flex-wrap items-center justify-between gap-4 border-b border-line bg-panel px-5 py-3">
        <div className="flex min-w-0 items-center gap-3">
          <div
            className={cx(
              "flex size-10 shrink-0 items-center justify-center rounded-xl",
              GROUP_STYLE.insight.tile,
            )}
          >
            <BlockIcon kind="analytics" className="size-5" />
          </div>
          <div className="min-w-0">
            <h2 id="analytics-title" className="truncate text-lg font-semibold">
              Analytics · {block.label}
            </h2>
            <p className="text-xs text-muted">
              {run ? "Saved data of the current run" : "Live read of the connected sources"} ·
              counted by rules, no AI
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="secondary"
            size="sm"
            data-testid="analytics-refresh"
            onClick={() => setReload((n) => n + 1)}
          >
            Refresh
          </Button>
          <Button
            variant="secondary"
            size="sm"
            data-testid="analytics-fullscreen"
            onClick={toggleFullscreen}
            aria-label={isFullscreen ? "Leave full screen" : "Enter full screen"}
          >
            {isFullscreen ? <MinimizeIcon className="size-4" /> : <MaximizeIcon className="size-4" />}
            {isFullscreen ? "Exit full screen" : "Full screen"}
          </Button>
          <button
            type="button"
            aria-label="Close analytics"
            data-testid="analytics-close"
            className="rounded-lg p-2 text-muted hover:bg-panel-2 hover:text-ink"
            onClick={() => dataflowStore.getState().closeAnalytics()}
          >
            <XIcon className="size-5" />
          </button>
        </div>
      </header>
      <AnalyticsBody state={state} block={block} tab={tab} setTab={setTab} />
    </div>
  );
}

function AnalyticsBody({
  state,
  block,
  tab,
  setTab,
}: {
  state: LoadState;
  block: WorkflowBlock;
  tab: TabId;
  setTab: (tab: TabId) => void;
}) {
  if (state.status === "loading") {
    return (
      <div className="grid flex-1 place-items-center text-sm text-muted" data-testid="analytics-loading">
        Reading the inputs and counting…
      </div>
    );
  }
  if (state.status === "error") {
    return (
      <div className="grid flex-1 place-items-center p-8">
        <p role="alert" className="max-w-lg text-center text-sm text-danger">
          {state.message}
        </p>
      </div>
    );
  }
  return <ReadyBody inputs={state.inputs} dataset={state.dataset} block={block} tab={tab} setTab={setTab} />;
}

function ReadyBody({
  inputs,
  dataset,
  block,
  tab,
  setTab,
}: {
  inputs: AnalyticsInput[];
  dataset: Extract<LoadState, { status: "ready" }>["dataset"];
  block: WorkflowBlock;
  tab: TabId;
  setTab: (tab: TabId) => void;
}) {
  const [filters, setFiltersState] = useState<AnalyticsFilters>({});
  const setFilters = useCallback(
    (patch: Partial<AnalyticsFilters>) => setFiltersState((f) => ({ ...f, ...patch })),
    [],
  );
  const rows = useMemo(() => applyFilters(dataset.rows, filters), [dataset, filters]);

  const countrySlots = useMemo(() => colorSlots(countByCountry(dataset.rows)), [dataset]);
  const granularitySetting = TimeGranularity.catch("auto").parse(block.params.timeGranularity);
  const extent = useMemo(() => timeExtent(dataset.rows), [dataset]);
  const granularity = useMemo(() => {
    if (granularitySetting !== "auto") return granularitySetting;
    return autoGranularity(dataset.rows.flatMap((r) => (r.time === null ? [] : [r.time])));
  }, [granularitySetting, dataset]);
  const phrases = useMemo(
    () =>
      String(block.params.phrases ?? "")
        .split("\n")
        .map((p) => p.trim())
        .filter(Boolean),
    [block.params.phrases],
  );

  const value: AnalyticsContextValue = useMemo(
    () => ({
      dataset,
      inputs,
      rows,
      allRows: dataset.rows,
      filters,
      setFilters,
      inputColor: (index) => seriesColor(index),
      countryColor: (code) => {
        const slot = countrySlots.get(code);
        return slot === undefined ? OTHER_COLOR : seriesColor(slot);
      },
      granularity,
      granularitySetting,
      setGranularity: (next) =>
        dataflowStore.getState().setParams(block.id, { ...block.params, timeGranularity: next }),
      phrases,
      setPhrases: (next) =>
        dataflowStore
          .getState()
          .setParams(block.id, { ...block.params, phrases: next.join("\n").slice(0, 5000) }),
      blockLabel: block.label,
    }),
    [dataset, inputs, rows, filters, setFilters, countrySlots, granularity, granularitySetting, phrases, block],
  );

  const Active = TABS.find((t) => t.id === tab)!.Component;
  const people = peopleCount(rows);

  return (
    <AnalyticsContext.Provider value={value}>
      <InputStrip inputs={inputs} />
      <nav
        className="flex shrink-0 gap-1 overflow-x-auto border-b border-line bg-panel px-5"
        role="tablist"
        aria-label="Analytics views"
      >
        {TABS.map((t) => (
          <button
            key={t.id}
            type="button"
            role="tab"
            aria-selected={tab === t.id}
            data-testid={`analytics-tab-${t.id}`}
            onClick={() => setTab(t.id)}
            className={cx(
              "shrink-0 border-b-2 px-3 py-2.5 text-sm font-medium whitespace-nowrap",
              tab === t.id ? "border-brand text-brand" : "border-transparent text-muted hover:text-ink",
            )}
          >
            {t.label}
          </button>
        ))}
      </nav>
      <FilterBar extent={extent} />
      <main className="min-h-0 flex-1 overflow-auto px-5 py-4" role="tabpanel">
        {dataset.rows.length === 0 ? (
          <NothingYet inputs={inputs} />
        ) : (
          <>
            <p className="mb-3 text-xs text-muted" data-testid="analytics-count">
              {rows.length === dataset.rows.length
                ? `All ${formatNumber(rows.length)} records`
                : `${formatNumber(rows.length)} of ${formatNumber(dataset.rows.length)} records match the filters`}{" "}
              · {formatNumber(people)} {dataset.idColumn ? "people" : "records counted as people"}
            </p>
            <Active />
          </>
        )}
      </main>
    </AnalyticsContext.Provider>
  );
}

function InputStrip({ inputs }: { inputs: AnalyticsInput[] }) {
  return (
    <div
      className="flex shrink-0 flex-wrap gap-2 border-b border-line bg-panel px-5 py-2"
      data-testid="analytics-inputs"
    >
      {inputs.map((input) => (
        <div
          key={input.port}
          className="flex items-center gap-2 rounded-lg border border-line bg-panel-2 px-2.5 py-1 text-xs"
          title={input.message}
        >
          <span
            aria-hidden="true"
            className="inline-block size-2.5 rounded-sm"
            style={{ background: seriesColor(input.index) }}
          />
          <span className="font-medium text-ink">{input.label}</span>
          <span className={cx(input.status === "error" ? "text-danger" : "text-muted")}>
            {input.status === "ready"
              ? `${formatNumber(input.data?.records.length ?? 0)} records · ${formatNumber(input.data?.sources.length ?? 0)} sources`
              : input.status === "unconnected"
                ? "not connected"
                : input.status === "needs_run"
                  ? "needs a run"
                  : input.status === "error"
                    ? "couldn't be read"
                    : "reading…"}
          </span>
        </div>
      ))}
    </div>
  );
}

function NothingYet({ inputs }: { inputs: AnalyticsInput[] }) {
  return (
    <div className="mx-auto mt-12 max-w-xl rounded-xl border border-dashed border-line bg-panel p-8 text-center">
      <h3 className="text-base font-semibold">Nothing to count yet</h3>
      <p className="mt-2 text-sm text-muted">
        Connect a Raw or Research block to an input of this block. Sources show right away; data that
        passes through other blocks shows after the flow has run.
      </p>
      <ul className="mt-4 space-y-1 text-left text-sm">
        {inputs.map((i) => (
          <li key={i.port} className="flex gap-2">
            <span className="font-medium">{i.label}:</span>
            <span className="text-muted">{i.message ?? (i.status === "ready" ? "no records" : i.status)}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { cx } from "@/lib/cx";
import { useAnalytics } from "./context";
import { countByCountry } from "./engine/aggregate";
import { formatDay, parseTime } from "./engine/time";
import { SENTIMENTS, UNKNOWN_KEY, type Sentiment } from "./engine/types";
import { formatNumber } from "./charts/format";
import { SENTIMENT_COLOR, SENTIMENT_LABEL } from "./charts/palette";

/**
 * One row of filters above every chart: inputs, countries, sentiment, time range and a phrase
 * search. Filters only narrow what is counted; they never change colours or the data itself.
 */
export function FilterBar({ extent }: { extent: [number, number] | null }) {
  const { dataset, filters, setFilters, inputColor, countryColor } = useAnalytics();
  const countries = useMemo(() => countByCountry(dataset.rows), [dataset]);
  const active =
    !!filters.inputs?.length ||
    !!filters.countries?.length ||
    !!filters.sentiments?.length ||
    !!filters.topics?.length ||
    filters.from != null ||
    filters.to != null ||
    !!filters.search;

  const toggle = <T,>(list: T[] | undefined, value: T): T[] => {
    const set = new Set(list ?? []);
    if (set.has(value)) set.delete(value);
    else set.add(value);
    return [...set];
  };

  return (
    <div
      className="flex shrink-0 flex-wrap items-center gap-x-4 gap-y-2 border-b border-line bg-panel-2 px-5 py-2 text-xs"
      data-testid="analytics-filters"
    >
      {dataset.inputs.length > 1 && (
        <FilterGroup label="Inputs">
          {dataset.inputs.map((i) => (
            <Chip
              key={i.index}
              active={filters.inputs?.includes(i.index) ?? false}
              color={inputColor(i.index)}
              onClick={() => setFilters({ inputs: toggle(filters.inputs, i.index) })}
            >
              {i.label}
            </Chip>
          ))}
        </FilterGroup>
      )}

      {countries.length > 0 && !(countries.length === 1 && countries[0]!.key === UNKNOWN_KEY) && (
        <CountryPicker
          options={countries.map((c) => ({
            key: c.key,
            label: c.label,
            count: c.count,
            color: c.key === UNKNOWN_KEY ? undefined : countryColor(c.key),
          }))}
          selected={filters.countries ?? []}
          onChange={(next) => setFilters({ countries: next })}
        />
      )}

      {dataset.textual && (
        <FilterGroup label="Sentiment">
          {SENTIMENTS.map((s: Sentiment) => (
            <Chip
              key={s}
              active={filters.sentiments?.includes(s) ?? false}
              color={SENTIMENT_COLOR[s]}
              onClick={() => setFilters({ sentiments: toggle(filters.sentiments, s) })}
            >
              {SENTIMENT_LABEL[s]}
            </Chip>
          ))}
        </FilterGroup>
      )}

      {extent && (
        <FilterGroup label="Time">
          <DateField
            label="From"
            value={filters.from ?? null}
            placeholder={formatDay(extent[0])}
            onChange={(t) => setFilters({ from: t })}
          />
          <span className="text-muted">–</span>
          <DateField
            label="Until"
            value={filters.to != null ? filters.to - 86_400_000 : null}
            placeholder={formatDay(extent[1])}
            onChange={(t) => setFilters({ to: t === null ? null : t + 86_400_000 })}
          />
        </FilterGroup>
      )}

      {dataset.textual && <SearchField value={filters.search ?? ""} onChange={(search) => setFilters({ search })} />}

      {filters.topics?.length ? (
        <FilterGroup label="Topics">
          {filters.topics.map((t) => (
            <Chip key={t} active onClick={() => setFilters({ topics: toggle(filters.topics, t) })}>
              {t} ×
            </Chip>
          ))}
        </FilterGroup>
      ) : null}

      {active && (
        <button
          type="button"
          data-testid="analytics-reset-filters"
          className="ml-auto rounded-md px-2 py-1 font-medium text-brand hover:bg-brand-soft"
          onClick={() =>
            setFilters({
              inputs: [],
              countries: [],
              sentiments: [],
              topics: [],
              from: null,
              to: null,
              search: "",
            })
          }
        >
          Reset filters
        </button>
      )}
    </div>
  );
}

function FilterGroup({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex flex-wrap items-center gap-1.5" role="group" aria-label={label}>
      <span className="mr-0.5 font-medium text-muted">{label}</span>
      {children}
    </div>
  );
}

function Chip({
  active,
  color,
  onClick,
  children,
}: {
  active: boolean;
  color?: string;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      aria-pressed={active}
      onClick={onClick}
      className={cx(
        "flex h-6 items-center gap-1.5 rounded-full border px-2 font-medium transition",
        active
          ? "border-brand bg-brand-soft text-ink"
          : "border-line bg-panel text-muted hover:text-ink",
      )}
    >
      {color && (
        <span aria-hidden="true" className="inline-block size-2 rounded-full" style={{ background: color }} />
      )}
      {children}
    </button>
  );
}

function CountryPicker({
  options,
  selected,
  onChange,
}: {
  options: { key: string; label: string; count: number; color?: string }[];
  selected: string[];
  onChange: (next: string[]) => void;
}) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const close = (e: MouseEvent) => {
      if (!ref.current?.contains(e.target as Node)) setOpen(false);
    };
    window.addEventListener("mousedown", close);
    return () => window.removeEventListener("mousedown", close);
  }, [open]);
  const summary =
    selected.length === 0
      ? "All countries"
      : selected.length <= 3
        ? selected.map((k) => options.find((o) => o.key === k)?.label ?? k).join(", ")
        : `${selected.length} countries`;
  return (
    <div className="relative" ref={ref}>
      <FilterGroup label="Country">
        <button
          type="button"
          data-testid="analytics-country-filter"
          aria-expanded={open}
          onClick={() => setOpen((v) => !v)}
          className={cx(
            "flex h-6 items-center gap-1 rounded-full border px-2.5 font-medium",
            selected.length ? "border-brand bg-brand-soft text-ink" : "border-line bg-panel text-muted",
          )}
        >
          {summary} ▾
        </button>
      </FilterGroup>
      {open && (
        <div className="absolute top-8 left-0 z-20 max-h-80 w-64 overflow-auto rounded-lg border border-line bg-panel p-1 shadow-xl">
          {options.map((o) => (
            <label
              key={o.key}
              className="flex cursor-pointer items-center gap-2 rounded-md px-2 py-1.5 text-ink hover:bg-panel-2"
            >
              <input
                type="checkbox"
                className="accent-brand"
                checked={selected.includes(o.key)}
                onChange={() =>
                  onChange(
                    selected.includes(o.key) ? selected.filter((k) => k !== o.key) : [...selected, o.key],
                  )
                }
              />
              {o.color && (
                <span aria-hidden="true" className="inline-block size-2 rounded-full" style={{ background: o.color }} />
              )}
              <span className="flex-1 truncate">{o.label}</span>
              <span className="text-muted tabular-nums">{formatNumber(o.count)}</span>
            </label>
          ))}
        </div>
      )}
    </div>
  );
}

function DateField({
  label,
  value,
  placeholder,
  onChange,
}: {
  label: string;
  value: number | null;
  placeholder: string;
  onChange: (t: number | null) => void;
}) {
  const [draft, setDraft] = useState(value === null ? "" : formatDay(value));
  useEffect(() => setDraft(value === null ? "" : formatDay(value)), [value]);
  const commit = () => {
    if (!draft.trim()) return onChange(null);
    const t = parseTime(draft);
    if (t !== null) onChange(t);
    else setDraft(value === null ? "" : formatDay(value));
  };
  return (
    <input
      aria-label={`${label} date`}
      value={draft}
      placeholder={placeholder}
      onChange={(e) => setDraft(e.target.value)}
      onBlur={commit}
      onKeyDown={(e) => e.key === "Enter" && commit()}
      className="h-6 w-24 rounded-md border border-line bg-panel px-1.5 text-ink placeholder:text-muted/70 focus:border-brand focus:outline-none"
    />
  );
}

function SearchField({ value, onChange }: { value: string; onChange: (v: string) => void }) {
  const [draft, setDraft] = useState(value);
  useEffect(() => setDraft(value), [value]);
  // Counting 10k+ comments on every key stroke is wasteful: apply after a short pause.
  useEffect(() => {
    if (draft === value) return;
    const id = setTimeout(() => onChange(draft), 250);
    return () => clearTimeout(id);
  }, [draft, value, onChange]);
  return (
    <FilterGroup label="Says">
      <input
        type="search"
        data-testid="analytics-search"
        aria-label="Only records that say"
        value={draft}
        placeholder='e.g. seat | "head-up display" | charg*'
        onChange={(e) => setDraft(e.target.value)}
        className="h-6 w-60 rounded-md border border-line bg-panel px-2 text-ink placeholder:text-muted/70 focus:border-brand focus:outline-none"
      />
    </FilterGroup>
  );
}

