import { emptyPipelineData, type PipelineData, type SourceKind } from "@reqflow/core";
import type { AnalyticsInput } from "./types";

/**
 * Synthetic data for the analytics tests: invented comments, never BMW's. Shaped like a feedback
 * export (ID, Country, Feedback Type, comment, date, a constant Brand column, a classification
 * column) and like a sales table (one row per market, one volume column per year).
 */
export interface FakeRow {
  id: string;
  country?: string;
  type?: string | string[];
  text: string;
  date?: string;
  engine?: string;
}

export function feedbackData(
  rows: readonly FakeRow[],
  opts: { source?: string; kind?: SourceKind; dateHeader?: string } = {},
): PipelineData {
  const sourceId = `src_${opts.source ?? "feedback"}`;
  return {
    ...emptyPipelineData(),
    sources: [
      {
        id: sourceId,
        kind: opts.kind ?? "customer_feedback",
        origin: "bmw_internal",
        title: `${opts.source ?? "feedback"}.xlsx`,
        retrievedAt: "2026-10-01T00:00:00.000Z",
      },
    ],
    records: rows.map((r, i) => ({
      id: `rec_${opts.source ?? "feedback"}_${i + 2}`,
      sourceId,
      text: r.text,
      locator: `row ${i + 2}`,
      market: "EU",
      fields: {
        ID: r.id,
        Brand: "BMW",
        Country: r.country ?? null,
        "Feedback Type": r.type ?? null,
        "Customer Feedback": r.text,
        ...(r.date !== undefined ? { [opts.dateHeader ?? "Date"]: r.date } : {}),
        "Engine Type": r.engine ?? "ICE",
      },
    })),
  };
}

export function salesData(): PipelineData {
  const sourceId = "src_sales";
  const markets: [string, string, number, number, number][] = [
    ["Germany", "DE", 120, 130, 150],
    ["France", "FR", 80, 70, 90],
    ["Italy", "IT", 60, 65, 40],
  ];
  return {
    ...emptyPipelineData(),
    sources: [
      {
        id: sourceId,
        kind: "sales_volume",
        origin: "bmw_internal",
        title: "sales.xlsx",
        retrievedAt: "2026-10-01T00:00:00.000Z",
      },
    ],
    records: markets.map(([market, code, a, b, c], i) => ({
      id: `rec_sales_${i + 2}`,
      sourceId,
      text: `market: ${market}; market_code: ${code}; volume_2024: ${a}; volume_2025: ${b}; volume_2030: ${c}`,
      fields: { market, market_code: code, volume_2024: a, volume_2025: b, volume_2030: c },
      locator: `row ${i + 2}`,
    })),
  };
}

export function readyInput(index: number, label: string, data: PipelineData): AnalyticsInput {
  return { index, port: `in-${index}`, label, status: "ready", data };
}

/** Twelve invented comments across three countries and three months. */
export const SAMPLE_ROWS: FakeRow[] = [
  { id: "A1", country: "DE", type: "Complaint", text: "The seat is uncomfortable on long trips.", date: "2025-01-10" },
  { id: "A2", country: "DE", type: "Praise", text: "Great navigation and a very quiet cabin.", date: "2025-01-22" },
  { id: "A3", country: "GB", type: "Complaint", text: "Wind noise above 120 km/h is annoying.", date: "2025-02-03" },
  { id: "A4", country: "GB", type: "Suggestion", text: "Please add wireless Apple CarPlay.", date: "2025-02-14" },
  { id: "A5", country: "FR", type: "Complaint", text: "The seat heating takes too long.", date: "2025-02-20" },
  { id: "A6", country: "FR", type: "Praise", text: "Love the design and the comfortable seat.", date: "2025-03-01" },
  { id: "A7", country: "DE", type: "Complaint", text: "Navigation lags and the screen freezes.", date: "2025-03-05" },
  { id: "A8", country: "DE", type: "Praise", text: "Excellent handling and steering.", date: "2025-03-09" },
  { id: "A1", country: "DE", type: "Complaint", text: "Also the trunk is too small.", date: "2025-03-12" },
  { id: "A9", country: "GB", type: "Complaint", text: "Road noise on the motorway.", date: "2025-03-15" },
  { id: "A10", type: "Suggestion", text: "A bigger screen would be nice.", date: "2025-03-20" },
  { id: "A11", country: "Germany", type: ["Complaint", "Praise"], text: "Good seat, bad noise.", date: "2025-03-28" },
];

import { describe, expect, it } from "vitest";
import { buildDataset, yearOfHeader } from "./dataset";
import { feedbackData, readyInput, salesData, SAMPLE_ROWS } from "./fixtures";
import type { AnalyticsInput } from "./types";

const NOW = Date.UTC(2026, 9, 11);

describe("buildDataset", () => {
  const dataset = buildDataset([readyInput(0, "F70", feedbackData(SAMPLE_ROWS))], { now: NOW });

  it("detects country, time, person and sentiment columns and says so", () => {
    expect(dataset.countryColumn).toBe("Country");
    expect(dataset.timeColumn).toBe("Date");
    expect(dataset.idColumn).toBe("ID");
    expect(dataset.sentimentColumn).toBe("Feedback Type");
    expect(dataset.textual).toBe(true);
    expect(dataset.notes.join(" ")).toMatch(/Country from the column "Country"/);
    expect(dataset.notes.join(" ")).toMatch(/Time from the column "Date" \(12 of 12 records dated\)/);
    const roles = Object.fromEntries(dataset.columns.map((c) => [c.name, c.role]));
    expect(roles["Customer Feedback"]).toBe("text");
    expect(roles.Brand).toBe("other"); // one value only: not a dimension
    expect(dataset.categoryColumns[0]).toBe("Feedback Type");
    expect(dataset.categoryColumns).toContain("Engine Type");
  });

  it("normalises countries and keeps records without one as unknown", () => {
    const codes = dataset.rows.map((r) => r.country);
    expect(codes.filter((c) => c === "DE")).toHaveLength(6); // "Germany" became DE
    expect(codes).toContain(null);
  });

  it("parses times in UTC and counts people by ID", () => {
    expect(dataset.rows[0]!.time).toBe(Date.UTC(2025, 0, 10));
    const people = new Set(dataset.rows.map((r) => r.person));
    expect(people.size).toBe(11); // A1 wrote twice
  });

  it("takes sentiment from the classification column, majority wins, a tie is neutral", () => {
    expect(dataset.rows[0]!.sentiment).toBe("negative");
    expect(dataset.rows[0]!.sentimentFrom).toBe("column");
    expect(dataset.rows[1]!.sentiment).toBe("positive");
    expect(dataset.rows[3]!.sentiment).toBe("neutral"); // Suggestion
    expect(dataset.rows[11]!.sentiment).toBe("neutral"); // Complaint + Praise
  });

  it("tags topics by the rule lexicon", () => {
    expect(dataset.rows[0]!.topics).toContain("seats");
    expect(dataset.rows[2]!.topics).toContain("noise");
  });

  it("uses the user's column names when given, and notes unknown ones", () => {
    const custom = buildDataset([readyInput(0, "F70", feedbackData(SAMPLE_ROWS))], {
      countryColumn: "engine type",
      timeColumn: "Nope",
      now: NOW,
    });
    expect(custom.countryColumn).toBe("Engine Type");
    expect(custom.timeColumn).toBe("Date");
    expect(custom.notes.join(" ")).toMatch(/no column "Nope"/);
  });

  it("works without a time column and says the timeline will fill in later", () => {
    const undated = buildDataset(
      [readyInput(0, "F70", feedbackData(SAMPLE_ROWS.map(({ date: _d, ...r }) => r)))],
      { now: NOW },
    );
    expect(undated.timeColumn).toBeNull();
    expect(undated.rows.every((r) => r.time === null)).toBe(true);
    expect(undated.notes.join(" ")).toMatch(/No time column yet/);
  });

  it("finds a date column by its values even with an unusual name", () => {
    const odd = buildDataset(
      [readyInput(0, "F70", feedbackData(SAMPLE_ROWS, { dateHeader: "Eingang" }))],
      { now: NOW },
    );
    expect(odd.timeColumn).toBe("Eingang");
  });

  it("reads year columns of a sales table as a time series with plans", () => {
    const sales = buildDataset([readyInput(0, "Sales", salesData())], { now: NOW });
    expect(sales.textual).toBe(false);
    expect(sales.countryColumn).toBe("market_code");
    expect(sales.yearSeries).toHaveLength(9);
    const de2030 = sales.yearSeries.find((p) => p.country === "DE" && p.year === 2030)!;
    expect(de2030).toMatchObject({ value: 150, planned: true });
    expect(sales.yearSeries.find((p) => p.year === 2025)!.planned).toBe(false);
    expect(sales.rows.every((r) => r.topics.length === 0 && r.sentiment === "neutral")).toBe(true);
  });

  it("keeps inputs apart and skips the ones that aren't ready", () => {
    const inputs: AnalyticsInput[] = [
      readyInput(0, "A", feedbackData(SAMPLE_ROWS.slice(0, 4), { source: "a" })),
      { index: 1, port: "in-1", label: "B", status: "needs_run", data: null, message: "run" },
      readyInput(2, "C", feedbackData(SAMPLE_ROWS.slice(4, 6), { source: "c" })),
    ];
    const ds = buildDataset(inputs, { now: NOW });
    expect(ds.inputs.map((i) => [i.label, i.records])).toEqual([
      ["A", 4],
      ["B", 0],
      ["C", 2],
    ]);
    expect(ds.rows.filter((r) => r.input === 2)).toHaveLength(2);
  });

  it("returns an empty dataset without notes when nothing arrived", () => {
    const empty = buildDataset([], { now: NOW });
    expect(empty.rows).toEqual([]);
    expect(empty.notes).toEqual([]);
  });

  it("reads years from headers", () => {
    expect(yearOfHeader("volume_2024")).toBe(2024);
    expect(yearOfHeader("Sales 2030")).toBe(2030);
    expect(yearOfHeader("ID")).toBeNull();
    expect(yearOfHeader("code12345")).toBeNull();
  });
});

import { describe, expect, it } from "vitest";
import {
  applyFilters,
  compareFeatures,
  compareShares,
  countByCountry,
  countByTopic,
  crossTab,
  flowData,
  normalCdf,
  peopleCount,
  phraseStats,
  segmentsOf,
  sentimentSplit,
  timeSeries,
} from "./aggregate";
import { buildDataset } from "./dataset";
import { feedbackData, readyInput, SAMPLE_ROWS } from "./fixtures";
import { UNKNOWN_KEY } from "./types";

const NOW = Date.UTC(2026, 9, 11);
const dataset = buildDataset(
  [
    readyInput(0, "A", feedbackData(SAMPLE_ROWS.slice(0, 8), { source: "a" })),
    readyInput(1, "B", feedbackData(SAMPLE_ROWS.slice(8), { source: "b" })),
  ],
  { now: NOW },
);
const rows = dataset.rows;

describe("analytics counting", () => {
  it("counts people once per ID", () => {
    expect(rows).toHaveLength(12);
    expect(peopleCount(rows)).toBe(11);
  });

  it("counts countries with shares and an explicit unknown", () => {
    const counts = countByCountry(rows);
    expect(counts[0]).toMatchObject({ key: "DE", label: "Germany", count: 6, people: 5 });
    expect(counts[0]!.share).toBeCloseTo(0.5);
    expect(counts.find((c) => c.key === UNKNOWN_KEY)).toMatchObject({ label: "No country", count: 1 });
  });

  it("counts a record once per topic it mentions", () => {
    const topics = countByTopic(rows);
    const seats = topics.find((t) => t.key === "seats")!;
    expect(seats.count).toBe(4);
    expect(topics.some((t) => t.key === UNKNOWN_KEY)).toBe(false);
  });

  it("filters by input, country, sentiment, time and phrase", () => {
    expect(applyFilters(rows, { inputs: [1] })).toHaveLength(4);
    expect(applyFilters(rows, { countries: ["GB"] })).toHaveLength(3);
    expect(applyFilters(rows, { countries: [UNKNOWN_KEY] })).toHaveLength(1);
    expect(applyFilters(rows, { sentiments: ["positive"] })).toHaveLength(3);
    expect(
      applyFilters(rows, { from: Date.UTC(2025, 2, 1), to: Date.UTC(2025, 3, 1) }),
    ).toHaveLength(7);
    expect(applyFilters(rows, { search: "seat | trunk" })).toHaveLength(5);
    expect(applyFilters(rows, { topics: ["noise"] }).length).toBeGreaterThanOrEqual(3);
  });

  it("splits sentiment in a fixed order", () => {
    expect(Object.keys(sentimentSplit(rows))).toEqual(["positive", "neutral", "negative"]);
    const split = sentimentSplit(rows);
    expect(split.positive + split.neutral + split.negative).toBe(12);
  });

  it("builds contiguous monthly series, records and shares", () => {
    const [all] = timeSeries(rows, "month", [
      { key: "all", label: "All", colorIndex: 0, includes: () => true },
    ]);
    expect(all!.points.map((p) => [p.label, p.value])).toEqual([
      ["Jan 2025", 2],
      ["Feb 2025", 3],
      ["Mar 2025", 7],
    ]);
    const [noise] = timeSeries(
      rows,
      "month",
      [
        {
          key: "noise",
          label: "Noise",
          colorIndex: 0,
          includes: () => true,
          counts: (r) => r.topics.includes("noise"),
        },
      ],
      "share",
    );
    expect(noise!.points[0]!.value).toBe(0);
    expect(noise!.points[1]!.value).toBeCloseTo(1 / 3);
  });

  it("cross-tabulates shares per row group", () => {
    const { values, counts } = crossTab(rows, (r) => r.country, (r) => r.topics);
    expect(counts.GB!.noise).toBe(2);
    expect(values.GB!.noise).toBeCloseTo(2 / 3);
  });

  it("finds what people say with record and people shares", () => {
    const stats = phraseStats(rows, "seat*")!;
    expect(stats.count).toBe(4);
    expect(stats.share).toBeCloseTo(4 / 12);
    expect(stats.people).toBe(4);
    expect(phraseStats(rows, "   ")).toBeNull();
  });

  it("compares shares with a two-proportion z-test and refuses tiny samples", () => {
    expect(normalCdf(0)).toBeCloseTo(0.5, 6);
    expect(normalCdf(1.96)).toBeCloseTo(0.975, 3);
    const big = compareShares(60, 100, 40, 100);
    expect(big.delta).toBeCloseTo(0.2);
    expect(big.p).toBeLessThan(0.01);
    expect(big.significant).toBe(true);
    const tiny = compareShares(2, 3, 0, 3);
    expect(tiny.enoughData).toBe(false);
    expect(tiny.significant).toBe(false);
  });

  it("segments by input with fixed colours and compares features against the rest", () => {
    const segments = segmentsOf(dataset, rows, "input");
    expect(segments.map((s) => [s.label, s.colorIndex, s.rows.length])).toEqual([
      ["A", 0, 8],
      ["B", 1, 4],
    ]);
    const [negative] = compareFeatures(segments, [
      { key: "neg", label: "Negative", test: (r) => r.sentiment === "negative" },
    ]);
    expect(negative!.cells.map((c) => c.count)).toEqual([4, 2]);
    expect(negative!.spread).toBeCloseTo(0);
    const byCountry = segmentsOf(dataset, rows, "country");
    expect(byCountry[0]!.key).toBe("DE");
    expect(segmentsOf(dataset, rows, "category:Feedback Type").map((s) => s.key)).toContain(
      "Complaint",
    );
  });

  it("builds flow-chart nodes and links that conserve records", () => {
    const flow = flowData(
      rows,
      [
        { label: "Input", keyOf: (r) => String(r.input), labelOf: (k) => k, colorOf: () => "red" },
        { label: "Country", keyOf: (r) => r.country, labelOf: (k) => k, colorOf: () => "blue" },
        { label: "Sentiment", keyOf: (r) => r.sentiment, labelOf: (k) => k, colorOf: () => "grey" },
      ],
      2,
    );
    const out = (stage: number) =>
      flow.links.filter((l) => l.source.startsWith(`${stage}:`)).reduce((a, l) => a + l.value, 0);
    expect(out(0)).toBe(12);
    expect(out(1)).toBe(12);
    const countryNodes = flow.nodes.filter((n) => n.stage === 1).map((n) => n.label);
    expect(countryNodes).toEqual(["DE", "GB", "Other (1)", "Unknown"]);
  });
});

