import type { ReactNode } from "react";
import { cx } from "@/lib/cx";
import { countryLabel } from "../engine/aggregate";
import { SENTIMENTS, UNKNOWN_KEY, type CountRow, type Sentiment } from "../engine/types";
import type { BarItem } from "../charts/BarList";
import type { ChartTable } from "../charts/ChartCard";
import type { StackRow } from "../charts/StackedBars";
import { formatNumber, formatPercent } from "../charts/format";
import { OTHER_COLOR, SENTIMENT_COLOR, SENTIMENT_LABEL } from "../charts/palette";

/** Helpers every tab shares: grids, toggles, and turning counts into chart items and tables. */

export function TabGrid({ testId, children }: { testId: string; children: ReactNode }) {
  return (
    <div data-testid={testId} className="grid gap-4 xl:grid-cols-2">
      {children}
    </div>
  );
}

/** A row of controls above the charts of a tab. */
export function Toolbar({ children, className }: { children: ReactNode; className?: string }) {
  return (
    <div className={cx("flex flex-wrap items-center gap-x-5 gap-y-2 xl:col-span-2", className)}>
      {children}
    </div>
  );
}

export function ToolbarItem({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="flex items-center gap-2 text-xs">
      <span className="font-medium text-muted">{label}</span>
      {children}
    </div>
  );
}

export function toggle<T>(list: readonly T[] | undefined, value: T): T[] {
  const set = new Set(list ?? []);
  if (set.has(value)) set.delete(value);
  else set.add(value);
  return [...set];
}

/** Count rows → ranked bars ("1,204 · 42%", people in the tooltip). */
export function barItems(
  counts: readonly CountRow[],
  colorOf: (key: string) => string,
  peopleLabel = "people",
): BarItem[] {
  return counts.map((c) => ({
    key: c.key,
    label: c.label,
    value: c.count,
    share: c.share,
    color: c.key === UNKNOWN_KEY ? OTHER_COLOR : colorOf(c.key),
    detail: `${formatNumber(c.people)} ${peopleLabel}`,
  }));
}

/** The same counts as a table: label, records, share, people. */
export function countTable(
  counts: readonly CountRow[],
  first: string,
  withPeople = true,
): ChartTable {
  return {
    columns: withPeople ? [first, "Records", "Share", "People"] : [first, "Records", "Share"],
    rows: counts.map((c) =>
      withPeople
        ? [c.label, formatNumber(c.count), formatPercent(c.share), formatNumber(c.people)]
        : [c.label, formatNumber(c.count), formatPercent(c.share)],
    ),
  };
}

/** One 100% bar per group with its positive / neutral / negative parts, colours fixed. */
export function sentimentStack(
  key: string,
  label: string,
  split: Record<Sentiment, number>,
): StackRow {
  return {
    key,
    label,
    parts: SENTIMENTS.map((s) => ({
      key: s,
      label: SENTIMENT_LABEL[s],
      value: split[s],
      color: SENTIMENT_COLOR[s],
    })),
  };
}

export function sentimentTable(rows: readonly StackRow[], first: string): ChartTable {
  return {
    columns: [first, "Records", ...SENTIMENTS.map((s) => SENTIMENT_LABEL[s])],
    rows: rows.map((row) => {
      const total = row.parts.reduce((a, p) => a + p.value, 0) || 1;
      return [
        row.label,
        formatNumber(row.parts.reduce((a, p) => a + p.value, 0)),
        ...row.parts.map((p) => `${formatPercent(p.value / total)} (${formatNumber(p.value)})`),
      ];
    }),
  };
}

export { countryLabel };

/** "records" or "people": what a person is, given whether the data has an ID column. */
export function peopleWord(hasId: boolean): string {
  return hasId ? "people" : "records (no ID column)";
}

/** Small muted paragraph explaining where a number comes from. */
export function Explain({ children }: { children: ReactNode }) {
  return <p className="text-xs leading-relaxed text-muted">{children}</p>;
}

import { useMemo } from "react";
import { useAnalytics } from "../context";
import {
  countByCountry,
  countByTopic,
  peopleCount,
  sentimentSplit,
  timeExtent,
  timeSeries,
} from "../engine/aggregate";
import { topTerms } from "../engine/text";
import { formatDay } from "../engine/time";
import { SENTIMENTS, UNKNOWN_KEY } from "../engine/types";
import { BarList } from "../charts/BarList";
import { ChartCard, EmptyChart } from "../charts/ChartCard";
import { Donut } from "../charts/Donut";
import { LineChart } from "../charts/LineChart";
import { StatGrid, StatTile } from "../charts/StatTile";
import { formatNumber, formatPercent } from "../charts/format";
import { SENTIMENT_COLOR, SENTIMENT_LABEL, seriesColor } from "../charts/palette";
import { barItems, countTable, TabGrid, toggle } from "./shared";
import { YearSeriesCharts } from "./YearSeriesCharts";

const GRANULARITY_WORD = { day: "day", week: "week", month: "month", quarter: "quarter", year: "year" };

/** The one-screen summary: headline numbers, then the most useful chart of every other tab. */
export function OverviewTab() {
  const { dataset, rows, filters, setFilters, countryColor, inputColor, granularity } =
    useAnalytics();
  const countries = useMemo(() => countByCountry(rows), [rows]);
  const topics = useMemo(() => countByTopic(rows), [rows]);
  const split = useMemo(() => sentimentSplit(rows), [rows]);
  const extent = useMemo(() => timeExtent(rows), [rows]);
  const people = useMemo(() => peopleCount(rows), [rows]);
  const series = useMemo(
    () =>
      timeSeries(rows, granularity, [
        { key: "all", label: "Records", colorIndex: 0, includes: () => true },
      ]),
    [rows, granularity],
  );
  const phrases = useMemo(
    () => (dataset.textual ? topTerms(rows.map((r) => r.text), { ngram: 2, limit: 10 }) : []),
    [rows, dataset.textual],
  );
  const knownCountries = countries.filter((c) => c.key !== UNKNOWN_KEY);
  const inputCounts = dataset.inputs.map((i) => ({
    ...i,
    count: rows.filter((r) => r.input === i.index).length,
  }));

  return (
    <TabGrid testId="analytics-overview">
      <div className="xl:col-span-2">
        <StatGrid>
          <StatTile testId="kpi-records" label="Records" value={formatNumber(rows.length)} hint="comments or rows counted" />
          <StatTile
            testId="kpi-people"
            label="People"
            value={formatNumber(people)}
            hint={dataset.idColumn ? `distinct "${dataset.idColumn}"` : "no ID column: one per record"}
          />
          <StatTile
            testId="kpi-countries"
            label="Countries"
            value={formatNumber(knownCountries.length)}
            hint={knownCountries[0] ? `most: ${knownCountries[0].label} (${formatPercent(knownCountries[0].share)})` : "no country column"}
          />
          <StatTile
            testId="kpi-time"
            label="Time span"
            value={extent ? `${formatDay(extent[0]).slice(0, 7)} – ${formatDay(extent[1]).slice(0, 7)}` : "No dates yet"}
            hint={extent ? `${formatPercent(rows.filter((r) => r.time !== null).length / (rows.length || 1))} dated` : "add a date column"}
          />
          {dataset.textual && (
            <StatTile
              testId="kpi-negative"
              label="Negative"
              value={formatPercent(rows.length ? split.negative / rows.length : 0)}
              hint={`${formatNumber(split.negative)} records · ${formatPercent(rows.length ? split.positive / rows.length : 0)} positive`}
            />
          )}
          {dataset.textual && (
            <StatTile
              testId="kpi-topic"
              label="Top topic"
              value={topics[0]?.label ?? "–"}
              hint={topics[0] ? `${formatPercent(topics[0].share)} of records` : "no topic words found"}
            />
          )}
        </StatGrid>
      </div>

      <ChartCard
        title="Records by country"
        subtitle="Click a country to filter every view"
        table={countTable(countries, "Country")}
        testId="chart-overview-countries"
      >
        {knownCountries.length ? (
          <BarList
            items={barItems(countries, countryColor)}
            limit={10}
            ariaLabel="Records by country"
            selectedKeys={filters.countries}
            onSelect={(key) => setFilters({ countries: toggle(filters.countries, key) })}
          />
        ) : (
          <EmptyChart>
            No country column found. Name it in the block's <em>Country column</em> parameter.
          </EmptyChart>
        )}
      </ChartCard>

      {dataset.textual ? (
        <ChartCard
          title="Sentiment"
          subtitle={
            dataset.sentimentColumn
              ? `From "${dataset.sentimentColumn}" where it names one, else a word list`
              : "From an English and German word list (rules, no AI)"
          }
          table={{
            columns: ["Sentiment", "Records", "Share"],
            rows: SENTIMENTS.map((s) => [
              SENTIMENT_LABEL[s],
              formatNumber(split[s]),
              formatPercent(rows.length ? split[s] / rows.length : 0),
            ]),
          }}
          testId="chart-overview-sentiment"
        >
          <Donut
            slices={SENTIMENTS.map((s) => ({
              key: s,
              label: SENTIMENT_LABEL[s],
              value: split[s],
              color: SENTIMENT_COLOR[s],
            }))}
            centerValue={formatNumber(rows.length)}
            centerLabel="records"
            ariaLabel="Sentiment split"
            onSelect={(key) =>
              setFilters({ sentiments: toggle(filters.sentiments, key as (typeof SENTIMENTS)[number]) })
            }
          />
        </ChartCard>
      ) : (
        <ChartCard title="Inputs" subtitle="Records per input" testId="chart-overview-inputs">
          <Donut
            slices={inputCounts.map((i) => ({
              key: String(i.index),
              label: i.label,
              value: i.count,
              color: inputColor(i.index),
            }))}
            centerValue={formatNumber(rows.length)}
            centerLabel="records"
            ariaLabel="Records per input"
          />
        </ChartCard>
      )}

      {dataset.textual && (
        <ChartCard
          title="What people talk about"
          subtitle="Share of records that mention each topic (keyword rules; a record can mention several)"
          table={countTable(topics, "Topic")}
          testId="chart-overview-topics"
        >
          {topics.length ? (
            <BarList
              items={barItems(topics, () => seriesColor(0))}
              limit={10}
              showOther={false}
              max={rows.length}
              ariaLabel="Topics mentioned"
              selectedKeys={filters.topics}
              onSelect={(key) => setFilters({ topics: toggle(filters.topics, key) })}
            />
          ) : (
            <EmptyChart>None of the topic keywords occur in these records.</EmptyChart>
          )}
        </ChartCard>
      )}

      <ChartCard
        title="Over time"
        subtitle={extent ? `Records per ${GRANULARITY_WORD[granularity]}` : "Needs a date column"}
        table={
          series[0]
            ? {
                columns: ["Period", "Records"],
                rows: series[0].points.map((p) => [p.label, formatNumber(p.value)]),
              }
            : undefined
        }
        testId="chart-overview-time"
      >
        {series[0] ? (
          <LineChart series={series} area height={220} ariaLabel="Records over time" />
        ) : (
          <EmptyChart>
            No time column yet. The timeline fills in as soon as a dataset has a date, month,
            quarter or year column.
          </EmptyChart>
        )}
      </ChartCard>

      {dataset.textual && phrases.length > 0 && (
        <ChartCard
          title="Most used phrases"
          subtitle="Two-word phrases by the share of records that use them (stop words left out)"
          table={{
            columns: ["Phrase", "Records", "Share"],
            rows: phrases.map((p) => [p.term, formatNumber(p.docs), formatPercent(p.share)]),
          }}
          testId="chart-overview-phrases"
        >
          <BarList
            items={phrases.map((p) => ({
              key: p.term,
              label: p.term,
              value: p.docs,
              share: p.share,
              color: seriesColor(2),
            }))}
            showOther={false}
            ariaLabel="Most used phrases"
            onSelect={(term) => setFilters({ search: `"${term}"` })}
          />
        </ChartCard>
      )}

      {dataset.inputs.length > 1 && dataset.textual && (
        <ChartCard
          title="Inputs"
          subtitle="Records per input after the filters"
          table={{
            columns: ["Input", "Records"],
            rows: inputCounts.map((i) => [i.label, formatNumber(i.count)]),
          }}
          testId="chart-overview-inputs"
        >
          <Donut
            slices={inputCounts.map((i) => ({
              key: String(i.index),
              label: i.label,
              value: i.count,
              color: inputColor(i.index),
            }))}
            centerValue={formatNumber(rows.length)}
            centerLabel="records"
            ariaLabel="Records per input"
            onSelect={(key) => setFilters({ inputs: toggle(filters.inputs, Number(key)) })}
          />
        </ChartCard>
      )}

      {dataset.yearSeries.length > 0 && <YearSeriesCharts />}

      <ChartCard title="How this was counted" subtitle="Detected from the data, rules only" className="xl:col-span-2" testId="analytics-notes">
        <ul className="list-disc space-y-1 pl-5 text-sm text-ink">
          {dataset.notes.map((note) => (
            <li key={note}>{note}</li>
          ))}
        </ul>
      </ChartCard>
    </TabGrid>
  );
}

import type { Series, YearSeriesPoint } from "../engine/types";

/**
 * Year columns ("volume_2024", "volume_2025", "volume_2030") read as one time series per row:
 * grouped by the column name without its year, one line per row label. Only the years that are
 * columns become buckets, so a gap (2025 → 2030) shows as one step, which the chart notes.
 */
export interface YearGroup {
  name: string; // "volume"
  years: number[];
  series: Series[];
  /** Bucket start of the first year after this one (a plan), or undefined when all are actuals. */
  dashedFrom?: number;
  irregular: boolean; // years aren't consecutive
}

export const yearStart = (year: number) => Date.UTC(year, 0, 1);

/** "volume_2024" → "volume", "Sales 2030" → "Sales", "2025" → "Value". */
export function yearGroupName(column: string): string {
  const name = column
    .replace(/(19|20)\d{2}/, "")
    .replace(/[\s_\-./]+$/g, "")
    .replace(/^[\s_\-./]+/g, "")
    .trim();
  return name || "Value";
}

export function groupYearSeries(
  points: readonly YearSeriesPoint[],
  opts: {
    labelOf: (point: YearSeriesPoint) => string;
    colorIndexOf: (point: YearSeriesPoint, order: number) => number;
    inputs: number;
    inputLabel: (index: number) => string;
  },
): YearGroup[] {
  const groups = new Map<string, YearSeriesPoint[]>();
  for (const p of points) {
    const name = yearGroupName(p.column);
    const list = groups.get(name) ?? [];
    list.push(p);
    groups.set(name, list);
  }
  return [...groups.entries()].map(([name, list]) => {
    const years = [...new Set(list.map((p) => p.year))].sort((a, b) => a - b);
    const lines = new Map<string, { label: string; first: YearSeriesPoint; byYear: Map<number, number> }>();
    for (const p of list) {
      const key = `${p.input}:${p.label}`;
      let line = lines.get(key);
      if (!line) {
        const label = opts.labelOf(p);
        line = {
          label: opts.inputs > 1 ? `${label} · ${opts.inputLabel(p.input)}` : label,
          first: p,
          byYear: new Map(),
        };
        lines.set(key, line);
      }
      line.byYear.set(p.year, (line.byYear.get(p.year) ?? 0) + p.value);
    }
    const series: Series[] = [...lines.entries()].map(([key, line], order) => ({
      key,
      label: line.label,
      colorIndex: opts.colorIndexOf(line.first, order),
      points: years.map((year) => ({
        t: yearStart(year),
        label: String(year),
        value: line.byYear.get(year) ?? 0,
      })),
    }));
    const firstPlanned = list.filter((p) => p.planned).map((p) => p.year).sort((a, b) => a - b)[0];
    return {
      name,
      years,
      series,
      ...(firstPlanned !== undefined ? { dashedFrom: yearStart(firstPlanned) } : {}),
      irregular: years.some((y, i) => i > 0 && y !== years[i - 1]! + 1),
    };
  });
}

import { useMemo } from "react";
import { useAnalytics } from "../context";
import { colorSlots, countByCountry, countryLabel } from "../engine/aggregate";
import { ChartCard } from "../charts/ChartCard";
import { LineChart } from "../charts/LineChart";
import { formatNumber } from "../charts/format";
import { groupYearSeries } from "./year-series";

/** Figures per year from year columns (e.g. sales volumes with plan years), one chart per measure. */
export function YearSeriesCharts() {
  const { dataset, allRows, filters } = useAnalytics();
  const groups = useMemo(() => {
    const slots = colorSlots(countByCountry(allRows));
    const points = dataset.yearSeries.filter(
      (p) =>
        (!filters.inputs?.length || filters.inputs.includes(p.input)) &&
        (!filters.countries?.length || (p.country !== null && filters.countries.includes(p.country))),
    );
    return groupYearSeries(points, {
      labelOf: (p) => (p.country ? countryLabel(p.country) : p.label),
      colorIndexOf: (p, order) => (p.country ? (slots.get(p.country) ?? 8) : order),
      inputs: dataset.inputs.length,
      inputLabel: (i) => dataset.inputs.find((x) => x.index === i)?.label ?? `Input ${i + 1}`,
    });
  }, [dataset, allRows, filters.inputs, filters.countries]);

  return (
    <>
      {groups.map((group) => (
        <ChartCard
          key={group.name}
          title={`${group.name} per year`}
          subtitle={`From the year columns (${group.years.join(", ")}), one line per row`}
          className="xl:col-span-2"
          testId="chart-year-series"
          table={{
            columns: ["Row", ...group.years.map(String)],
            rows: group.series.map((s) => [s.label, ...s.points.map((p) => formatNumber(p.value))]),
          }}
          footnote={[
            group.dashedFrom !== undefined ? "Dashed: plan years after this one, not actuals." : "",
            group.irregular ? "Only the years that are columns are shown, so gaps between them are one step." : "",
          ]
            .filter(Boolean)
            .join(" ")}
        >
          <LineChart
            series={group.series}
            dashedFrom={group.dashedFrom}
            ariaLabel={`${group.name} per year`}
          />
        </ChartCard>
      ))}
    </>
  );
}

import { describe, expect, it } from "vitest";
import type { YearSeriesPoint } from "../engine/types";
import { groupYearSeries, yearGroupName, yearStart } from "./year-series";

const point = (
  column: string,
  year: number,
  label: string,
  value: number,
  planned = false,
  input = 0,
): YearSeriesPoint => ({ column, year, label, country: label, input, value, planned });

describe("year series", () => {
  it("names groups without their year", () => {
    expect(yearGroupName("volume_2024")).toBe("volume");
    expect(yearGroupName("Sales 2030")).toBe("Sales");
    expect(yearGroupName("2025")).toBe("Value");
  });

  it("makes one line per row with only the years that are columns, dashed from the first plan", () => {
    const [group] = groupYearSeries(
      [
        point("volume_2024", 2024, "DE", 120),
        point("volume_2025", 2025, "DE", 130),
        point("volume_2030", 2030, "DE", 150, true),
        point("volume_2024", 2024, "FR", 80),
        point("volume_2030", 2030, "FR", 90, true),
      ],
      { labelOf: (p) => p.label, colorIndexOf: (_p, i) => i, inputs: 1, inputLabel: String },
    );
    expect(group!.name).toBe("volume");
    expect(group!.years).toEqual([2024, 2025, 2030]);
    expect(group!.irregular).toBe(true);
    expect(group!.dashedFrom).toBe(yearStart(2030));
    expect(group!.series.map((s) => [s.label, s.points.map((p) => p.value)])).toEqual([
      ["DE", [120, 130, 150]],
      ["FR", [80, 0, 90]],
    ]);
  });

  it("names the input when several inputs carry year columns", () => {
    const groups = groupYearSeries(
      [point("units 2024", 2024, "DE", 1, false, 0), point("units 2024", 2024, "DE", 2, false, 1)],
      {
        labelOf: (p) => p.label,
        colorIndexOf: (_p, i) => i,
        inputs: 2,
        inputLabel: (i) => ["A", "B"][i]!,
      },
    );
    expect(groups[0]!.series.map((s) => s.label)).toEqual(["DE · A", "DE · B"]);
    expect(groups[0]!.dashedFrom).toBeUndefined();
    expect(groups[0]!.irregular).toBe(false);
  });
});

import { useMemo } from "react";
import { useAnalytics } from "../context";
import {
  countByCountry,
  countByRegion,
  countByTopic,
  countryLabel,
  crossTab,
  sentimentSplit,
} from "../engine/aggregate";
import { topicLabel } from "../engine/topics";
import { UNKNOWN_KEY } from "../engine/types";
import { BarList } from "../charts/BarList";
import { ChartCard, EmptyChart } from "../charts/ChartCard";
import { Donut } from "../charts/Donut";
import { GroupedBars } from "../charts/GroupedBars";
import { Heatmap } from "../charts/Heatmap";
import { StackedBars } from "../charts/StackedBars";
import { formatNumber, formatPercent } from "../charts/format";
import { seriesColor } from "../charts/palette";
import { barItems, countTable, sentimentStack, sentimentTable, TabGrid, toggle } from "./shared";

/** Regions in a fixed order, so each keeps its colour whatever the filters leave. */
const REGIONS = [
  "Europe",
  "China",
  "North America",
  "Asia-Pacific",
  "Middle East & Africa",
  "Latin America",
  "Other",
];

/** Where the records come from, and how what people say differs by country. */
export function CountriesTab() {
  const { dataset, rows, filters, setFilters, countryColor, inputColor } = useAnalytics();
  const countries = useMemo(() => countByCountry(rows), [rows]);
  const known = countries.filter((c) => c.key !== UNKNOWN_KEY);
  const regions = useMemo(() => countByRegion(rows), [rows]);
  const top = known.slice(0, 10);

  const sentimentRows = useMemo(
    () =>
      top.map((c) =>
        sentimentStack(c.key, c.label, sentimentSplit(rows.filter((r) => r.country === c.key))),
      ),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [rows, countries],
  );

  const heat = useMemo(() => {
    const topics = countByTopic(rows).slice(0, 10);
    const tab = crossTab(
      rows,
      (r) => r.country,
      (r) => r.topics,
    );
    return { topics, ...tab };
  }, [rows]);

  const mix = useMemo(() => {
    const categories = known.slice(0, 12).map((c) => ({ key: c.key, label: c.label }));
    const values: Record<string, Record<string, number>> = {};
    for (const input of dataset.inputs) {
      const ofInput = rows.filter((r) => r.input === input.index);
      for (const c of categories) {
        (values[c.key] ??= {})[String(input.index)] = ofInput.length
          ? ofInput.filter((r) => r.country === c.key).length / ofInput.length
          : 0;
      }
    }
    return { categories, values };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rows, countries, dataset.inputs]);

  if (!known.length) {
    const candidates = dataset.columns
      .filter((c) => c.role === "category" || c.role === "other")
      .slice(0, 8)
      .map((c) => `"${c.name}"`);
    return (
      <TabGrid testId="analytics-countries">
        <div className="xl:col-span-2">
          <EmptyChart>
            No country column found in these inputs, so there is nothing to count by country. Name
            it in the block's <em>Country column</em> parameter
            {candidates.length ? ` (columns here: ${candidates.join(", ")})` : ""}.
          </EmptyChart>
        </div>
      </TabGrid>
    );
  }

  return (
    <TabGrid testId="analytics-countries">
      <ChartCard
        title="Records by country"
        subtitle="How many records come from each country · click to filter"
        table={countTable(countries, "Country")}
        testId="chart-countries"
      >
        <BarList
          items={barItems(countries, countryColor)}
          limit={20}
          ariaLabel="Records by country"
          selectedKeys={filters.countries}
          onSelect={(key) => setFilters({ countries: toggle(filters.countries, key) })}
        />
      </ChartCard>

      <ChartCard
        title="By region"
        subtitle="Countries grouped into BMW's market regions"
        table={countTable(regions, "Region")}
        testId="chart-regions"
      >
        <Donut
          slices={REGIONS.flatMap((region, i) => {
            const c = regions.find((r) => r.key === region);
            return c ? [{ key: region, label: region, value: c.count, color: seriesColor(i) }] : [];
          })}
          centerValue={formatNumber(known.reduce((a, c) => a + c.count, 0))}
          centerLabel="with a country"
          ariaLabel="Records by region"
        />
      </ChartCard>

      {dataset.textual && (
        <ChartCard
          title="Sentiment by country"
          subtitle={
            dataset.sentimentColumn
              ? `From "${dataset.sentimentColumn}" where it names one, else a word list · top 10 countries`
              : "From an English and German word list · top 10 countries"
          }
          table={sentimentTable(sentimentRows, "Country")}
          testId="chart-country-sentiment"
        >
          <StackedBars
            rows={sentimentRows}
            ariaLabel="Sentiment by country"
            onSelect={(country, sentiment) =>
              setFilters({
                countries: [country],
                sentiments: [sentiment as "positive" | "neutral" | "negative"],
              })
            }
          />
        </ChartCard>
      )}

      {dataset.textual && heat.topics.length > 0 && (
        <ChartCard
          title="Topics by country"
          subtitle="Share of each country's records that mention the topic · click a cell to filter"
          className="xl:col-span-2"
          testId="chart-country-topics"
          table={{
            columns: ["Country", ...heat.topics.map((t) => t.label)],
            rows: top.map((c) => [
              c.label,
              ...heat.topics.map((t) => formatPercent(heat.values[c.key]?.[t.key] ?? 0)),
            ]),
          }}
        >
          <Heatmap
            rows={top.map((c) => ({ key: c.key, label: c.label, total: c.count }))}
            columns={heat.topics.map((t) => ({ key: t.key, label: topicLabel(t.key) }))}
            values={heat.values}
            cellDetail={(country, topic) => {
              const n = heat.counts[country]?.[topic] ?? 0;
              const total = top.find((c) => c.key === country)?.count ?? 0;
              return `${formatNumber(n)} of ${formatNumber(total)} records`;
            }}
            ariaLabel="Topics by country"
            onSelect={(country, topic) => setFilters({ countries: [country], topics: [topic] })}
          />
        </ChartCard>
      )}

      {dataset.inputs.length > 1 && (
        <ChartCard
          title="Country mix per input"
          subtitle="Share of each input's records from the country, so inputs of different size compare fairly"
          className="xl:col-span-2"
          testId="chart-country-mix"
          table={{
            columns: ["Country", ...dataset.inputs.map((i) => i.label)],
            rows: mix.categories.map((c) => [
              c.label,
              ...dataset.inputs.map((i) => formatPercent(mix.values[c.key]?.[String(i.index)] ?? 0)),
            ]),
          }}
        >
          <GroupedBars
            categories={mix.categories}
            series={dataset.inputs.map((i) => ({
              key: String(i.index),
              label: i.label,
              color: inputColor(i.index),
            }))}
            values={mix.values}
            valueFormat={formatPercent}
            axisFormat={formatPercent}
            ariaLabel="Country mix per input"
            onSelect={(country) => setFilters({ countries: toggle(filters.countries, country) })}
          />
        </ChartCard>
      )}

      {dataset.yearSeries.length > 0 && <FiguresByCountry />}
    </TabGrid>
  );
}

/** The latest actual year of each year column, per country (e.g. sales volume 2025). */
function FiguresByCountry() {
  const { dataset, countryColor } = useAnalytics();
  const actualYears = dataset.yearSeries.filter((p) => !p.planned).map((p) => p.year);
  const year = actualYears.length
    ? Math.max(...actualYears)
    : Math.max(...dataset.yearSeries.map((p) => p.year));
  const points = dataset.yearSeries.filter((p) => p.year === year);
  const column = points[0]?.column ?? String(year);
  const total = points.reduce((a, p) => a + p.value, 0) || 1;
  const items = points.map((p, i) => ({
    key: `${p.input}:${p.label}:${i}`,
    label: p.country ? countryLabel(p.country) : p.label,
    value: p.value,
    share: p.value / total,
    color: p.country ? countryColor(p.country) : seriesColor(0),
  }));
  return (
    <ChartCard
      title={`${column} by country`}
      subtitle={`The latest ${actualYears.length ? "actual" : "planned"} year (${year}) of the year columns`}
      testId="chart-country-figures"
      table={{
        columns: ["Row", String(year), "Share"],
        rows: items.map((i) => [i.label, formatNumber(i.value), formatPercent(i.share)]),
      }}
    >
      <BarList items={items} showOther={false} ariaLabel={`${column} by country`} />
    </ChartCard>
  );
}

import { colorSlots, countByCountry, countryLabel, type SeriesSpec } from "../engine/aggregate";
import type { AnalyticsRow, Series } from "../engine/types";

/** How the main timeline splits its lines. */
export type TimelineSplit = "total" | "inputs" | "countries" | "sentiment";
/** What the main timeline counts per bucket. */
export type TimelineMetric = "records" | "people" | "negative" | "positive";

/**
 * Line definitions for the main timeline. Colours follow the entity: inputs their port slot,
 * countries their slot in the whole dataset (the rest share "Other"), and sentiment uses the slots
 * whose hues match the sentiment tokens (positive = M blue slot 0, negative = M red slot 1,
 * neutral = grey "Other").
 */
export function timelineSpecs(
  split: TimelineSplit,
  metric: TimelineMetric,
  ctx: {
    allRows: readonly AnalyticsRow[];
    inputs: readonly { index: number; label: string }[];
  },
): SeriesSpec[] {
  const counts =
    metric === "negative"
      ? (r: AnalyticsRow) => r.sentiment === "negative"
      : metric === "positive"
        ? (r: AnalyticsRow) => r.sentiment === "positive"
        : undefined;
  const withCounts = (spec: Omit<SeriesSpec, "counts">): SeriesSpec =>
    counts ? { ...spec, counts } : spec;

  if (split === "inputs") {
    return ctx.inputs.map((i) =>
      withCounts({
        key: `input-${i.index}`,
        label: i.label,
        colorIndex: i.index,
        includes: (r) => r.input === i.index,
      }),
    );
  }
  if (split === "countries") {
    const all = countByCountry(ctx.allRows).filter((c) => c.key !== "∅");
    const slots = colorSlots(all);
    const top = all.slice(0, 5).map((c) => c.key);
    const specs = top.map((code) =>
      withCounts({
        key: `country-${code}`,
        label: countryLabel(code),
        colorIndex: slots.get(code) ?? 8,
        includes: (r) => r.country === code,
      }),
    );
    if (all.length > top.length) {
      specs.push(
        withCounts({
          key: "country-other",
          label: "Other countries",
          colorIndex: 8,
          includes: (r) => r.country !== null && !top.includes(r.country),
        }),
      );
    }
    return specs;
  }
  if (split === "sentiment") {
    // Sentiment as lines counts each sentiment's records; a share metric would be trivially 0/1.
    return [
      { key: "positive", label: "Positive", colorIndex: 0, includes: (r) => r.sentiment === "positive" },
      { key: "negative", label: "Negative", colorIndex: 1, includes: (r) => r.sentiment === "negative" },
      { key: "neutral", label: "Neutral", colorIndex: 8, includes: (r) => r.sentiment === "neutral" },
    ];
  }
  return [withCounts({ key: "total", label: "All records", colorIndex: 0, includes: () => true })];
}

/** The bucket with the most records of the first series, or null without data. */
export function busiest(series: readonly Series[]): { label: string; value: number } | null {
  const points = series[0]?.points ?? [];
  let best: { label: string; value: number } | null = null;
  for (const p of points) if (!best || p.value > best.value) best = { label: p.label, value: p.value };
  return best && best.value > 0 ? best : null;
}

import { useMemo, useState } from "react";
import type { TimeGranularity } from "@reqflow/core";
import { Segmented } from "@/components/settings/Segmented";
import { useAnalytics } from "../context";
import { countByTopic, peopleCount, timeExtent, timeSeries } from "../engine/aggregate";
import { matchesPhrase, parsePhrase } from "../engine/text";
import { formatDay } from "../engine/time";
import { topicLabel } from "../engine/topics";
import { ChartCard, EmptyChart } from "../charts/ChartCard";
import { LineChart } from "../charts/LineChart";
import { StatGrid, StatTile } from "../charts/StatTile";
import { formatNumber, formatPercent } from "../charts/format";
import { TabGrid, Toolbar, ToolbarItem } from "./shared";
import { busiest, timelineSpecs, type TimelineMetric, type TimelineSplit } from "./timeline-helpers";
import { YearSeriesCharts } from "./YearSeriesCharts";

const BUCKETS: { value: TimeGranularity; label: string }[] = [
  { value: "auto", label: "Auto" },
  { value: "day", label: "Day" },
  { value: "week", label: "Week" },
  { value: "month", label: "Month" },
  { value: "quarter", label: "Quarter" },
  { value: "year", label: "Year" },
];

/** How things change over time: records, people or sentiment per bucket, split as you choose. */
export function TimelineTab() {
  const {
    dataset,
    rows,
    allRows,
    granularity,
    granularitySetting,
    setGranularity,
    phrases,
    setFilters,
  } = useAnalytics();
  const [metric, setMetric] = useState<TimelineMetric>("records");
  const [split, setSplit] = useState<TimelineSplit>("total");
  const extent = useMemo(() => timeExtent(rows), [rows]);
  const isShare = metric === "negative" || metric === "positive";

  const main = useMemo(
    () =>
      timeSeries(
        rows,
        granularity,
        timelineSpecs(split, metric, { allRows, inputs: dataset.inputs }),
        isShare && split !== "sentiment" ? "share" : metric === "people" ? "people" : "records",
      ),
    [rows, granularity, split, metric, allRows, dataset.inputs, isShare],
  );
  const phraseSeries = useMemo(() => {
    if (!dataset.textual || !phrases.length) return [];
    const parsed = phrases
      .slice(0, 8)
      .map((p) => ({ raw: p, query: parsePhrase(p) }))
      .filter((p) => p.query);
    return timeSeries(
      rows,
      granularity,
      parsed.map(({ raw, query }, i) => ({
        key: raw,
        label: raw,
        colorIndex: i,
        includes: () => true,
        counts: (r) => matchesPhrase(r.text, query!),
      })),
      "share",
    );
  }, [rows, granularity, phrases, dataset.textual]);
  const topicSeries = useMemo(() => {
    if (!dataset.textual) return [];
    const topics = countByTopic(rows).slice(0, 5);
    return timeSeries(
      rows,
      granularity,
      topics.map((t, i) => ({
        key: t.key,
        label: topicLabel(t.key),
        colorIndex: i,
        includes: () => true,
        counts: (r) => r.topics.includes(t.key),
      })),
      "share",
    );
  }, [rows, granularity, dataset.textual]);

  if (!extent) {
    return (
      <TabGrid testId="analytics-timeline">
        <div className="xl:col-span-2">
          <EmptyChart>
            <span>
              No time column yet — the timeline fills in automatically as soon as a dataset has a
              date, month, quarter or year column (e.g. Date, Created, Month, Year). You can also
              name it in the block's <em>Time column</em> parameter.
              {dataset.notes
                .filter((n) => /time/i.test(n))
                .map((n) => (
                  <span key={n} className="mt-2 block">
                    {n}
                  </span>
                ))}
            </span>
          </EmptyChart>
        </div>
        {dataset.yearSeries.length > 0 && <YearSeriesCharts />}
      </TabGrid>
    );
  }

  const peak = busiest(main);
  const dated = rows.filter((r) => r.time !== null).length;
  const buckets = main[0]?.points.length ?? 0;
  const unit = granularity;
  const valueFormat = isShare && split !== "sentiment" ? formatPercent : formatNumber;
  const metricWord =
    metric === "records"
      ? "Records"
      : metric === "people"
        ? "People"
        : `Share ${metric === "negative" ? "negative" : "positive"}`;

  return (
    <TabGrid testId="analytics-timeline">
      <Toolbar>
        <ToolbarItem label="Buckets">
          <Segmented
            options={BUCKETS}
            value={granularitySetting}
            onChange={setGranularity}
            testIdPrefix="timeline-bucket-"
          />
        </ToolbarItem>
        <ToolbarItem label="Count">
          <Segmented<TimelineMetric>
            options={[
              { value: "records", label: "Records" },
              { value: "people", label: "People" },
              ...(dataset.textual
                ? ([
                    { value: "negative", label: "Negative %" },
                    { value: "positive", label: "Positive %" },
                  ] as const)
                : []),
            ]}
            value={metric}
            onChange={setMetric}
            testIdPrefix="timeline-metric-"
          />
        </ToolbarItem>
        <ToolbarItem label="Split by">
          <Segmented<TimelineSplit>
            options={[
              { value: "total", label: "Total" },
              ...(dataset.inputs.length > 1 ? ([{ value: "inputs", label: "Inputs" }] as const) : []),
              { value: "countries", label: "Countries" },
              ...(dataset.textual ? ([{ value: "sentiment", label: "Sentiment" }] as const) : []),
            ]}
            value={split}
            onChange={setSplit}
            testIdPrefix="timeline-split-"
          />
        </ToolbarItem>
      </Toolbar>

      <ChartCard
        title={`${split === "sentiment" ? "Records by sentiment" : metricWord} per ${unit}`}
        subtitle={`${formatDay(extent[0])} to ${formatDay(extent[1])} · ${formatNumber(dated)} dated records · click a ${unit} to filter to it`}
        className="xl:col-span-2"
        testId="chart-timeline"
        table={{
          columns: [unit[0]!.toUpperCase() + unit.slice(1), ...main.map((s) => s.label)],
          rows: (main[0]?.points ?? []).map((p, i) => [
            p.label,
            ...main.map((s) => valueFormat(s.points[i]?.value ?? 0)),
          ]),
        }}
      >
        <LineChart
          series={main}
          area={main.length === 1}
          height={280}
          valueFormat={valueFormat}
          axisFormat={isShare && split !== "sentiment" ? formatPercent : undefined}
          yMax={isShare && split !== "sentiment" ? 1 : undefined}
          ariaLabel={`${metricWord} per ${unit}`}
          onSelectBucket={(t) => {
            const next = main[0]?.points.findIndex((p) => p.t === t) ?? -1;
            const end = main[0]?.points[next + 1]?.t ?? extent[1] + 1;
            setFilters({ from: t, to: end });
          }}
        />
      </ChartCard>

      <div className="xl:col-span-2">
        <StatGrid>
          <StatTile
            label={`Busiest ${unit}`}
            value={peak ? peak.label : "–"}
            hint={peak ? `${formatNumber(peak.value)} ${metric === "people" ? "people" : "records"}` : undefined}
          />
          <StatTile
            label="Dated records"
            value={formatPercent(rows.length ? dated / rows.length : 0)}
            hint={`${formatNumber(dated)} of ${formatNumber(rows.length)}`}
          />
          <StatTile label="Span" value={`${formatDay(extent[0])} – ${formatDay(extent[1])}`} />
          <StatTile
            label={`Average per ${unit}`}
            value={formatNumber(buckets ? dated / buckets : 0)}
            hint={`${formatNumber(peopleCount(rows))} people overall`}
          />
        </StatGrid>
      </div>

      {phraseSeries.length > 0 && (
        <ChartCard
          title="Tracked phrases over time"
          subtitle={`Share of records per ${unit} that say it (phrases from "What people say")`}
          testId="chart-timeline-phrases"
          table={{
            columns: ["Period", ...phraseSeries.map((s) => s.label)],
            rows: (phraseSeries[0]?.points ?? []).map((p, i) => [
              p.label,
              ...phraseSeries.map((s) => formatPercent(s.points[i]?.value ?? 0)),
            ]),
          }}
        >
          <LineChart
            series={phraseSeries}
            valueFormat={formatPercent}
            axisFormat={formatPercent}
            ariaLabel="Tracked phrases over time"
          />
        </ChartCard>
      )}

      {topicSeries.length > 0 && (
        <ChartCard
          title="Topics over time"
          subtitle={`The five most mentioned topics: share of records per ${unit}`}
          testId="chart-timeline-topics"
          className={phraseSeries.length ? undefined : "xl:col-span-2"}
          table={{
            columns: ["Period", ...topicSeries.map((s) => s.label)],
            rows: (topicSeries[0]?.points ?? []).map((p, i) => [
              p.label,
              ...topicSeries.map((s) => formatPercent(s.points[i]?.value ?? 0)),
            ]),
          }}
        >
          <LineChart
            series={topicSeries}
            valueFormat={formatPercent}
            axisFormat={formatPercent}
            ariaLabel="Topics over time"
          />
        </ChartCard>
      )}

      {dataset.yearSeries.length > 0 && <YearSeriesCharts />}
    </TabGrid>
  );
}

